/*
 * chromokit keys: ← and → turn the page, Ctrl+K (⌘K) and / open the search.
 *
 * ← and → follow the page's own previous and next links: `a[rel="prev"]` /
 * `a[rel="next"]`, or chromokit's `.cx-pagination__link--prev` / `--next`. They
 * act only when nothing that uses the arrows has focus — a field, a menu, a
 * block of code or a table that scrolls sideways, a slider, an open dialog —
 * and never with a modifier, since Alt+arrow is the browser's Back and Forward.
 *
 * The search key focuses (or clicks) the first `[data-cx-search]` element.
 */
;(() => {
  if (window.__chromokitKeys) return
  window.__chromokitKeys = true

  const OWN_KEYS =
    'input, textarea, select, [contenteditable]:not([contenteditable="false"]), dialog, pre, .highlight, .expressive-code, .cx-code, .cx-table-wrap, .tabbed-set, [role="tablist"], [role="slider"], [role="listbox"], [role="menu"]'

  const link = (rel) =>
    document.querySelector(`.cx-pagination__link--${rel}`) ||
    document.querySelector(`a[rel="${rel}"]`) ||
    document.querySelector(`a.${rel}-page`)

  const arrowsAreFree = (event) => {
    const target = event.target
    if (target instanceof Element && target.closest(OWN_KEYS)) return false
    if (document.querySelector('dialog[open]')) return false
    const active = document.activeElement
    if (active && active.shadowRoot) return false
    return true
  }

  document.addEventListener('keydown', (event) => {
    if (event.defaultPrevented) return
    const searchKey =
      ((event.ctrlKey || event.metaKey) && !event.altKey && !event.shiftKey && event.key.toLowerCase() === 'k') ||
      (event.key === '/' && !event.ctrlKey && !event.metaKey && !event.altKey)
    if (searchKey) {
      if (event.key === '/' && !arrowsAreFree(event)) return
      const search = document.querySelector('[data-cx-search]')
      if (!search) return
      event.preventDefault()
      const field = search.matches('input, textarea') ? search : search.querySelector('input')
      if (field) field.focus()
      else search.click()
      return
    }
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return
    if (!arrowsAreFree(event)) return
    const target = link(event.key === 'ArrowLeft' ? 'prev' : 'next')
    if (!target) return
    event.preventDefault()
    target.click()
  })
})()

/*
 * chromokit behaviours for a page with no framework: copy buttons on code,
 * the "On this page" highlight, tabs, and heading anchors.
 *
 * Each one looks for its own markup and does nothing when there is none, so
 * the file is safe on any page. Load it with `defer`.
 */
;(() => {
  if (window.__chromokitBehaviours) return
  window.__chromokitBehaviours = true

  const COPY =
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect width="14" height="14" x="8" y="8" rx="2" ry="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/></svg>'
  const CHECK =
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>'

  const ready = (fn) => (document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', fn) : fn())

  ready(() => {
    // Copy buttons, on every framed block of code that has none.
    for (const frame of document.querySelectorAll('.cx-code')) {
      if (frame.querySelector('.cx-code__copy')) continue
      const pre = frame.querySelector('pre')
      if (!pre || !navigator.clipboard) continue
      const button = document.createElement('button')
      button.type = 'button'
      button.className = 'cx-code__copy'
      button.setAttribute('aria-label', 'Copy to clipboard')
      button.innerHTML = COPY
      button.addEventListener('click', () => {
        navigator.clipboard.writeText(pre.innerText.replace(/\n$/, '')).then(() => {
          button.innerHTML = CHECK
          button.classList.add('is-done')
          setTimeout(() => {
            button.innerHTML = COPY
            button.classList.remove('is-done')
          }, 1500)
        })
      })
      frame.prepend(button)
    }

    // Heading anchors, for headings with an id inside prose.
    for (const heading of document.querySelectorAll('.cx-prose :is(h2, h3, h4)[id]')) {
      if (heading.querySelector('.cx-anchor')) continue
      const anchor = document.createElement('a')
      anchor.className = 'cx-anchor'
      anchor.href = `#${heading.id}`
      anchor.setAttribute('aria-label', 'Link to this section')
      heading.append(anchor)
    }

    // Tabs: buttons with aria-controls inside .cx-tabs.
    for (const strip of document.querySelectorAll('.cx-tabs')) {
      const tabs = [...strip.querySelectorAll('[role="tab"]')]
      const select = (tab) => {
        for (const other of tabs) {
          const selected = other === tab
          other.setAttribute('aria-selected', String(selected))
          other.tabIndex = selected ? 0 : -1
          const panel = document.getElementById(other.getAttribute('aria-controls') || '')
          if (panel) panel.hidden = !selected
        }
      }
      for (const tab of tabs) {
        tab.addEventListener('click', () => select(tab))
        tab.addEventListener('keydown', (event) => {
          const step = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0
          if (step === 0) return
          event.preventDefault()
          const next = tabs[(tabs.indexOf(tab) + step + tabs.length) % tabs.length]
          select(next)
          next.focus()
        })
      }
    }

    // "On this page": mark the section being read.
    const toc = document.querySelector('.cx-toc')
    if (toc && 'IntersectionObserver' in window) {
      const links = new Map()
      for (const a of toc.querySelectorAll('a[href^="#"]')) links.set(decodeURIComponent(a.hash.slice(1)), a)
      const headings = [...links.keys()].map((id) => document.getElementById(id)).filter(Boolean)
      let current = null
      const observer = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) {
            if (entry.isIntersecting) {
              current = entry.target.id
              break
            }
          }
          for (const [id, a] of links) a.classList.toggle('is-active', id === current)
        },
        { rootMargin: '-60px 0px -70% 0px' },
      )
      for (const heading of headings) observer.observe(heading)
    }
  })
})()
